        const s = switch (self) {
            .recall => "recall",
            .precision => "precision",
            .ndcg => "ndcg",
            .mrr => "mrr",
            .map => "map",
            .relevance => "relevance",
            .faithfulness => "faithfulness",
            .completeness => "completeness",
            .coherence => "coherence",
            .safety => "safety",
            .helpfulness => "helpfulness",
            .correctness => "correctness",
