            .{ "semantic", .semantic },
            .{ "bm25", .bm25 },
            .{ "metadata", .metadata },
            .{ "tree", .tree },
            .{ "graph", .graph },
            .{ "hybrid", .hybrid },
        });
        return map.get(s) orelse error.UnexpectedToken;
    }
};

